#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26
# Re-run ONLY the extractor (extract_fish_tasks.py, same arguments as post_run_pipeline.sh) for every TASK 4 session listed in
# task4_sessions_map.txt, after an extractor fix (2026-10-26: topic-consistent intra identity), then regenerate the summary file.
LD=${LD:-$HOME/fish_traces/night_20261025_final}; L=$LD/task4_reextract.log
log(){ echo "[$(date +%H:%M:%S)] $*" | tee -a "$L"; }
log "re-extract start ($(wc -l < "$LD/task4_sessions_map.txt") sessions)"
while read -r S FAM; do
  A=$HOME/fish_traces/analysis_$S; [ -d "$A" ] || { log "$S ($FAM): no analysis dir, skip"; continue; }
  cp -n "$A/fish_tasks.txt" "$A/fish_tasks_pre_reextract.txt" 2>/dev/null
  ( cd postprocess && python3 extract_fish_tasks.py "$S" -o "$A/fish_tasks.json" --releases "$A/releases.json" --show 6 > "$A/fish_tasks.txt" 2> "$A/fish_tasks.err" ) \
    && log "$S ($FAM): $(grep -oE 'trigger edges with instances: [0-9]+ \([^)]*\)' "$A/fish_tasks.txt") | $(grep -oE '[0-9]+ paired by address \(not paired: [^)]*\)' "$A/fish_tasks.txt" | cut -c1-120)" \
    || log "$S ($FAM): EXTRACTOR FAILED ($(tail -1 "$A/fish_tasks.err" | cut -c1-120))"
done < "$LD/task4_sessions_map.txt"
python3 scripts/task4_summary.py > notes/task4_summary_2026-10-26.txt 2>&1 && log "summary regenerated: notes/task4_summary_2026-10-26.txt"
log "re-extract DONE"
